-- 81 Sandstorm: one GPU particle cloud of 200,000 grains. `collide` parts
-- it round the rocks; an attractor following the twister draws it up and
-- spins it. The twister wanders; C and W switch each off and on.
-- Generated by tools/gen_scenes.py.

script = { tick_rate = 60 }

local nav = require("nav")
local SCENE = "scenes/81-sandstorm.scene"
local TWISTER = { follow = "Twister", strength = 0.9, swirl = 4.5, radius = 190.0 }
local captions = true
local storm, twister, status
local collide, whirl = true, true
local t = 0

local function show()
    UI.set_text(status, "200,000 grains   rocks " .. (collide and "on" or "off") .. "   whirlwind " .. (whirl and "on" or "off"))
end

function init(entity)
    storm = Entity.find_by_name("Storm")
    twister = Entity.find_by_name("Twister")
    status = Entity.find_by_name("Status")
    show()
end

function update(entity, dt)
    nav.tick(SCENE)
    t = t + dt
    if Input.is_key_just_pressed("Tab") then captions = nav.toggle_ui_captions(captions) end
    if Input.is_key_just_pressed("C") then
        collide = not collide
        Particles.set(storm, "collide", collide)
        show()
    end
    if Input.is_key_just_pressed("W") then
        whirl = not whirl
        local a = { follow = TWISTER.follow, strength = whirl and TWISTER.strength or 0,
                    swirl = whirl and TWISTER.swirl or 0, radius = TWISTER.radius }
        Particles.set(storm, "attractors", { a })
        Sprite.set_color(twister, 1, 1, 1, whirl and 0.9 or 0)
        show()
    end
    -- The twister wanders the dunes, leaning as it goes.
    local x = -60 + math.sin(t * 0.21) * 380 + math.sin(t * 0.53) * 60
    Transform.set_position(twister, x, -20 + math.sin(t * 1.7) * 10)
    Transform.set_rotation(twister, math.cos(t * 0.21) * 0.12)
end
